private boolean instantiateLoadConstraint(FullSensitiveNode objn, FullSensitiveNode qn, SegmentNode pts, int code) {
  int ret_type = GeometricManager.Undefined_Mapping;
  if ((code >> 8) == GeometricManager.ONE_TO_ONE) {
    pres.I1 = pts.I2;
    pres.I2 = pts.I1;
    switch (code & 255) {
      case GeometricManager.ONE_TO_ONE: pres.L = pts.L; ret_type = GeometricManager.ONE_TO_ONE; break;
      case GeometricManager.MANY_TO_MANY: pres.L = ((RectangleNode)pts).L_prime; pres.L_prime = pts.L; ret_type = GeometricManager.MANY_TO_MANY; break;
    }
  } else {
    pres.I1 = pts.I2;
    pres.I2 = 1;
    pres.L_prime = 1;
    switch (code & 255) {
      case GeometricManager.ONE_TO_ONE: pres.L = pts.L; ret_type = GeometricManager.MANY_TO_MANY; break;
      case GeometricManager.MANY_TO_MANY: pres.L = ((RectangleNode)pts).L_prime; ret_type = GeometricManager.MANY_TO_MANY; break;
    }
  }
  try {
    return objn.addFlowsTo(ret_type, qn);
  } catch (ClassCastException | NullPointerException | IllegalArgumentException e) {
    // Handle the exception (e.g., logging, cleanup, or a default return value)
    return false;
  }
}
